create table public.first_value_policies(id uuid primary key default gen_random_uuid(),code text not null,version integer not null,product_family text not null check(product_family in('hpm','guidebook','furnishing','investment_intelligence')),name text not null,description text not null,required_evidence_codes text[] not null,required_capability_codes text[] not null,evaluator_code text not null,completion_operation_code text not null,destination_resolver_code text not null,artifact_type text not null,supports_existing_artifact_reuse boolean not null,reuse_policy_code text,status text not null check(status in('draft','active','retired')),effective_from timestamptz not null,effective_until timestamptz,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(code,version));
create table public.first_value_action_definitions(id uuid primary key default gen_random_uuid(),code text not null,version integer not null,product_family text not null,responsibility text not null check(responsibility in('customer','internal','shared','system')),operation_code text not null,required_capability_codes text[] not null,prerequisite_action_codes text[] not null,completion_evidence_codes text[] not null,retry_policy_code text,validation_policy_code text,status text not null check(status in('active','retired')),unique(code,version));
create table public.first_value_journeys(id uuid primary key,tenant_id uuid not null,customer_account_id uuid not null,onboarding_case_id uuid references public.onboarding_cases(id),entitlement_source_id uuid not null references public.commercial_entitlements(id),product_family text not null check(product_family in('hpm','guidebook','furnishing','investment_intelligence')),source_type text not null check(source_type in('onboarding_handoff','existing_product_context','administrative_entry','migration','expansion')),source_reference_id text not null,product_context_type text not null,product_context_id uuid not null,policy_code text not null,policy_version integer not null,status text not null check(status in('pending','ready','in_progress','customer_action_required','internal_action_required','system_processing','blocked','ready_for_evaluation','completed','cancelled')),outcome_code text,blocker_code text,started_at timestamptz,completed_at timestamptz,cancelled_at timestamptz,idempotency_key_hash text not null unique,created_at timestamptz not null,updated_at timestamptz not null,revision integer not null default 1,foreign key(customer_account_id,tenant_id)references public.customer_accounts(id,tenant_id),foreign key(policy_code,policy_version)references public.first_value_policies(code,version),unique(source_reference_id,product_family));
create table public.first_value_action_instances(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,journey_id uuid not null references public.first_value_journeys(id),action_code text not null,action_version integer not null,status text not null check(status in('locked','available','in_progress','completed','blocked','failed')),responsibility text not null,attempt_count integer not null default 0,idempotency_key_hash text unique,started_at timestamptz,completed_at timestamptz,revision integer not null default 1,unique(journey_id,action_code,action_version));
create table public.first_value_evidence(id uuid primary key,tenant_id uuid not null,journey_id uuid not null references public.first_value_journeys(id),evidence_code text not null,evidence_version integer not null,source_type text not null check(source_type in('product_resource','domain_decision','validation_result','provider_observation','customer_confirmation','internal_confirmation','migration')),source_reference_type text not null,source_reference_id text not null,status text not null check(status in('valid','invalid','superseded')),evaluated_at timestamptz not null,expires_at timestamptz,created_at timestamptz not null,unique(journey_id,evidence_code,source_reference_type,source_reference_id));
create table public.first_value_evaluations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,journey_id uuid not null references public.first_value_journeys(id),achieved boolean not null,decision_code text not null,missing_evidence_codes text[] not null,next_action_code text,blocker_code text,policy_code text not null,policy_version integer not null,evaluated_at timestamptz not null,correlation_id text not null);
create table public.first_value_retry_attempts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,journey_id uuid not null references public.first_value_journeys(id),action_instance_id uuid references public.first_value_action_instances(id),attempt_number integer not null,status text not null check(status in('started','succeeded','retryable_failure','terminal_failure')),stable_failure_code text,correlation_id text not null,created_at timestamptz not null default now(),completed_at timestamptz,unique(journey_id,action_instance_id,attempt_number));
create table public.first_value_audit_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,journey_id uuid not null references public.first_value_journeys(id),event_type text not null,actor_id uuid,actor_type text not null check(actor_type in('customer','internal','system','migration')),reason_code text,correlation_id text not null,idempotency_key_hash text unique,occurred_at timestamptz not null default now());
create table public.first_value_notification_attempts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,journey_id uuid not null references public.first_value_journeys(id),recipient_user_id uuid not null references public.profiles(id),notification_type text not null,idempotency_key_hash text not null unique,status text not null check(status in('queued','sent','failed')),created_at timestamptz not null default now());
create index first_value_active_idx on public.first_value_journeys(tenant_id,customer_account_id,status,updated_at);create index first_value_blocked_idx on public.first_value_journeys(blocker_code,updated_at)where status='blocked';create index first_value_internal_idx on public.first_value_action_instances(responsibility,status)where responsibility in('internal','shared');create index first_value_processing_idx on public.first_value_action_instances(status,started_at)where status in('in_progress','failed');
create function public.prevent_active_first_value_definition_mutation()returns trigger language plpgsql set search_path='' as $$begin if old.status='active'then raise exception'Active first-value definitions are immutable';end if;return new;end$$;create trigger first_value_policy_immutable before update or delete on public.first_value_policies for each row execute function public.prevent_active_first_value_definition_mutation();create trigger first_value_action_immutable before update or delete on public.first_value_action_definitions for each row execute function public.prevent_active_first_value_definition_mutation();
alter table public.first_value_policies enable row level security;alter table public.first_value_action_definitions enable row level security;alter table public.first_value_journeys enable row level security;alter table public.first_value_action_instances enable row level security;alter table public.first_value_evidence enable row level security;alter table public.first_value_evaluations enable row level security;alter table public.first_value_retry_attempts enable row level security;alter table public.first_value_audit_events enable row level security;alter table public.first_value_notification_attempts enable row level security;
create policy "members read first value journeys"on public.first_value_journeys for select to authenticated using(exists(select 1 from public.customer_account_memberships m where m.customer_account_id=first_value_journeys.customer_account_id and m.tenant_id=first_value_journeys.tenant_id and m.profile_id=auth.uid()and m.status='active'));create policy "members read first value actions"on public.first_value_action_instances for select to authenticated using(exists(select 1 from public.first_value_journeys j join public.customer_account_memberships m on m.customer_account_id=j.customer_account_id and m.tenant_id=j.tenant_id where j.id=journey_id and m.profile_id=auth.uid()and m.status='active'));create policy "admins read first value definitions"on public.first_value_policies for select to authenticated using(public.is_admin());create policy "admins read first value action definitions"on public.first_value_action_definitions for select to authenticated using(public.is_admin());create policy "admins read first value evidence"on public.first_value_evidence for select to authenticated using(public.is_admin());create policy "admins read first value evaluations"on public.first_value_evaluations for select to authenticated using(public.is_admin());create policy "admins read first value retry"on public.first_value_retry_attempts for select to authenticated using(public.is_admin());create policy "admins read first value audit"on public.first_value_audit_events for select to authenticated using(public.is_admin());create policy "admins read first value notifications"on public.first_value_notification_attempts for select to authenticated using(public.is_admin());
revoke all on public.first_value_policies,public.first_value_action_definitions,public.first_value_journeys,public.first_value_action_instances,public.first_value_evidence,public.first_value_evaluations,public.first_value_retry_attempts,public.first_value_audit_events,public.first_value_notification_attempts from anon;revoke insert,update,delete on public.first_value_policies,public.first_value_action_definitions,public.first_value_journeys,public.first_value_action_instances,public.first_value_evidence,public.first_value_evaluations,public.first_value_retry_attempts,public.first_value_audit_events,public.first_value_notification_attempts from authenticated;grant select on public.first_value_journeys,public.first_value_action_instances to authenticated;
